export function makeSubmission(lesson,source){
 if(lesson.mode==='program') return source;
 return '#include <iostream>\n' + source + '\n\n// Game-owned test driver: each line is one independent check.\nint main() {\n' + lesson.tests.map(t=>'    std::cout << ('+t[0]+') << "\\n";').join('\n')+'\n}\n';
}
export const normalizeOutput=s=>s.replace(/\r/g,'').trimEnd();
export function checkOutput(lesson,result){return normalizeOutput(result)===normalizeOutput(lesson.expected);}
export function checkRequirements(lesson,source){
 // Small teaching nudges, not a security boundary or a general AST validator.
 const withoutComments=source.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\/\/[^\n]*/g,'');
 return (lesson.requirements||[]).filter(([pattern])=>!new RegExp(pattern).test(withoutComments)).map(x=>x[1]);
}
